SourceCode.Declaration:
/// <summary>
/// submitExceptions' request: unexpected items and verified-empty locations of one submission.
/// SubmissionId is the same idempotency key the counts were sent with.
/// </summary>
[DataContractAttribute]
class HSMobileOpsCountExceptionsRequest
{
    DataAreaId      dataAreaId;
    InventJournalId journalId;
    str             claimToken;
    str             submissionId;
    str             userId;
    str             deviceId;
    List            exceptions;
    List            emptyLocations;
    List            confirmations;

}

Method.Source:
[DataMemberAttribute('DataAreaId')]
public DataAreaId parmDataAreaId(DataAreaId _value = dataAreaId)
{
    dataAreaId = _value;
    return dataAreaId;
}

[DataMemberAttribute('JournalId')]
public InventJournalId parmJournalId(InventJournalId _value = journalId)
{
    journalId = _value;
    return journalId;
}

[DataMemberAttribute('ClaimToken')]
public str parmClaimToken(str _value = claimToken)
{
    claimToken = _value;
    return claimToken;
}

[DataMemberAttribute('SubmissionId')]
public str parmSubmissionId(str _value = submissionId)
{
    submissionId = _value;
    return submissionId;
}

[DataMemberAttribute('UserId')]
public str parmUserId(str _value = userId)
{
    userId = _value;
    return userId;
}

[DataMemberAttribute('DeviceId')]
public str parmDeviceId(str _value = deviceId)
{
    deviceId = _value;
    return deviceId;
}

[DataMemberAttribute('Exceptions'),
 DataCollectionAttribute(Types::Class, classStr(HSMobileOpsCountExceptionRow))]
public List parmExceptions(List _value = exceptions)
{
    exceptions = _value;
    return exceptions;
}

[DataMemberAttribute('EmptyLocations'),
 DataCollectionAttribute(Types::Class, classStr(HSMobileOpsCountEmptyLocationRow))]
public List parmEmptyLocations(List _value = emptyLocations)
{
    emptyLocations = _value;
    return emptyLocations;
}

/// <summary>
/// Verify-only lines (e.g. in transit) the counter confirmed instead of counting.
/// </summary>
[DataMemberAttribute('Confirmations'),
 DataCollectionAttribute(Types::Class, classStr(HSMobileOpsCountConfirmationRow))]
public List parmConfirmations(List _value = confirmations)
{
    confirmations = _value;
    return confirmations;
}
